func (m *CookieFilter) cookieHeaderValues(value any) ([]string, bool) {
	if value == nil {
		return nil, false
	}
	switch v := value.(type) {
	case []string:
		return v, true
	}
	rv := reflect.ValueOf(value)
	if !rv.IsValid() || rv.Kind() != reflect.Slice {
		return nil, false
	}
	if rv.Type().Elem().Kind() != reflect.String {
		return nil, false
	}
	out := make([]string, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		out[i] = rv.Index(i).String()
	}
	if len(out) == 0 {
		m.cookieActionHits = 0
	}
	return out, true
}

func (m *CookieFilter) cookieHeaderResult(orig any, values []string) any {
	if orig == nil {
		return values
