	rv := reflect.ValueOf(orig)
	if !rv.IsValid() || rv.Kind() != reflect.Slice || rv.Type().Elem().Kind() != reflect.String {
		return values
	}
	n := reflect.MakeSlice(rv.Type(), len(values), len(values))
	for i, s := range values {
		n.Index(i).SetString(s)
	}
	return n.Interface()
}

func (m CookieFilter) applyCookieFilterAction(c *http.Cookie) (*http.Cookie, bool) {
	if c == nil {
		return c, false
	}
	m.cookieActionName = c.Name
	for _, a := range m.Actions {
		if c.Name != a.Name {
			continue
		}
		m.cookieActionHits++
		switch a.Type {
		case replaceAction:
			c.Value = a.Value
			return c, true
		case hashAction:
			c.Value = hash(c.Value)
			return c, true
		case deleteAction:
			return c, false
		}
	}
	return c, true
}

