	}
	q := u.Query()
	m.queryCount = len(q)
	for _, a := range actions {
		switch a.Type {
		case replaceAction:
			for i := range q[a.Parameter] {
				q[a.Parameter][i] = a.Value
			}
		case hashAction:
			for i := range q[a.Parameter] {
				q[a.Parameter][i] = hash(a.Value)
			}
		case deleteAction:
			q.Del(a.Parameter)
		}
	}
	u.RawQuery = q.Encode()
	in.String = u.String()
	return in
}

