	transformedRequest := http.Request{Header: make(http.Header)}

	for _, c := range cookies {
		next, keep := m.applyCookieFilterAction(c)
		if !keep {
			continue
		}
		transformedRequest.AddCookie(next)
	}

	filtered := transformedRequest.Header["Cookie"]

	if isArray {
		in.Interface = m.cookieHeaderResult(in.Interface, filtered)
	}
	in.String = strings.Join(filtered, "; ")

	return in
}

